#include <bits/stdc++.h>
using namespace std;

class Solution {
    int answer = 0;
    int kValue = 0;
    vector<int> dfs(TreeNode* node) {
        if (!node) return {};
        vector<int> a = dfs(node->left), b = dfs(node->right);
        a.insert(a.end(), b.begin(), b.end());
        sort(a.begin(), a.end());
        if ((int)a.size() >= kValue && node->val > a[kValue - 1]) ++answer;
        a.push_back(node->val);
        sort(a.begin(), a.end());
        if ((int)a.size() > kValue) a.resize(kValue);
        return a;
    }
public:
    int countGreatEnoughNodes(TreeNode* root, int k) {
        answer = 0;
        kValue = k;
        dfs(root);
        return answer;
    }
};
